'use client';

import { Center } from '@lobehub/ui';
import { memo } from 'react';

import type { IconAvatarProps } from '@/features/IconAvatar';

import { TITLE } from '../style';

const KOLLAB_AVATAR_SRC = 'data:image/webp;base64,';

export type AvatarProps = Omit<IconAvatarProps, 'Icon'>;

const Avatar = memo<AvatarProps>(({ background, shape = 'circle', size, style, ...rest }) => {
  return (
    <Center
      flex={'none'}
      style={{
        background,
        borderRadius: shape === 'circle' ? '50%' : Math.floor(size * 0.1),
        height: size,
        overflow: 'hidden',
        width: size,
        ...style,
      }}
      {...rest}
    >
      <img
        alt={TITLE}
        aria-label={TITLE}
        height={size}
        src={KOLLAB_AVATAR_SRC}
        style={{
          display: 'block',
          height: '100%',
          objectFit: 'cover',
          width: '100%',
        }}
        width={size}
      />
    </Center>
  );
});

export default Avatar;

